import unittest
from candidate import decimal_to_binary

class TestDecimalToBinary(unittest.TestCase):
    def test_decimal_to_binary_for_zero(self):
        self.assertEqual(decimal_to_binary(0), "db0db")

    def test_decimal_to_binary_for_one(self):
        self.assertEqual(decimal_to_binary(1), "db1db")

    def test_decimal_to_binary_for_fifteen(self):
        self.assertEqual(decimal_to_binary(15), "db1111db")

    def test_decimal_to_binary_for_thirty_two(self):
        self.assertEqual(decimal_to_binary(32), "db100000db")

    def test_decimal_to_binary_for_large_number(self):
        self.assertEqual(decimal_to_binary(1024), "db10000000000db")

    def test_decimal_to_binary_format_starts_and_ends_with_db(self):
        result = decimal_to_binary(5)
        self.assertTrue(result.startswith("db"))
        self.assertTrue(result.endswith("db"))

    def test_decimal_to_binary_for_negative_integer(self):
        self.assertEqual(decimal_to_binary(-1), "db-1db")

    def test_decimal_to_binary_raises_type_error_for_none(self):
        with self.assertRaises(TypeError):
            decimal_to_binary(None)

    def test_decimal_to_binary_raises_type_error_for_string(self):
        with self.assertRaises(TypeError):
            decimal_to_binary("15")

    def test_decimal_to_binary_raises_type_error_for_float(self):
        with self.assertRaises(TypeError):
            decimal_to_binary(3.14)

    def test_decimal_to_binary_raises_type_error_for_empty_string(self):
        with self.assertRaises(TypeError):
            decimal_to_binary("")

    def test_decimal_to_binary_raises_type_error_for_list(self):
        with self.assertRaises(TypeError):
            decimal_to_binary([1, 2])

    def test_decimal_to_binary_content_contains_only_db_and_binary_digits(self):
        result = decimal_to_binary(7)
        inner = result[2:-2]
        self.assertTrue(all(c in "01-" for c in inner))

    def test_decimal_to_binary_for_power_of_two(self):
        self.assertEqual(decimal_to_binary(8), "db1000db")

    def test_decimal_to_binary_returns_string_type(self):
        self.assertIsInstance(decimal_to_binary(0), str)

if __name__ == '__main__':
    unittest.main()
